/* ================= CONFIG: edit these ================= */
const SITE_NAME   = "Ohio State Roleplay";
const SITE_LOGO   = "data:image/png;base64,";   // logo is embedded; you can swap in a path like "/img/logo.png"
const HERO_IMAGE  = "";   // optional background photo, e.g. "/img/hero.jpg"
const HERO_TITLE  = ["OHIO STATE", "ROLEPLAY"];
const HERO_SUB    = "Ohio's #1 Roleplay";
const DISCORD_INVITE = "https://discord.gg/ohiovc";
const PLAY_URL    = "https://erlc.gg/join/Ohiovc";                 // ERLC server link for the Play button (hardcode later)
const PANEL_URL   = "/panel";   // backend checks staff access            // where the moderation panel lives
const LOGIN_URL   = "/auth/login?mode=public";   // Discord sign-in for anyone (staff also get panel access)
const LOGOUT_URL  = "/auth/logout";
const ME_URL      = "/api/home/me";      // -> { id, username, avatar } or 401
const REVIEWS_URL = "/api/home/reviews";  // GET -> [{name,stars,text}], POST {stars,text}
const TEAM_URL    = "/api/home/team";     // fills in Discord names/photos left blank below
const ABOUT_BLOCKS = [   // image: index into ABOUT_IMAGES below (or paste a path/URL)
  { title: "Strict standards", sub: "Realistic rules, enforced fairly.",
    bullets: ["Active departments", "Strict departments", "Realism"], image: 0 },
  { title: "Ohio environment", sub: "Ohio roads and cities with real character.",
    bullets: ["Highways, cities and small towns", "Authentic local character", "Immersive world-building"], image: 1 }
];
const TEAM = [
  { id: "1498514468252942436", role: "Owner",    name: "", photo: "" },
  { id: "1536879503421345932", role: "Co-Owner", name: "", photo: "" }
];
/* ====================================================== */

/* embedded About images (swap for file paths whenever you like) */
const ABOUT_IMAGES = [
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,"
];

const $ = id => document.getElementById(id);
const esc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let user = null, stars = 5;

// static content
document.title = SITE_NAME;
if (SITE_LOGO) $('favicon').href = SITE_LOGO;
$('siteName').textContent = SITE_NAME;
if (SITE_LOGO) $('logo').src = SITE_LOGO; else $('logo').style.visibility = 'hidden';
if (HERO_IMAGE) document.querySelector('.hero').style.setProperty('--hero-img', `url("${HERO_IMAGE}")`);
$('heroTitle').innerHTML = HERO_TITLE.map(esc).join('<br>') + '<i></i>';
$('heroSub').textContent = HERO_SUB;
$('discordBtn').href = DISCORD_INVITE;
$('panelLink').href = PANEL_URL;
$('playBtn').href = PLAY_URL;
$('loginBtn').href = LOGIN_URL;
$('aboutRows').innerHTML = ABOUT_BLOCKS.map((b,i) => {
  const img = typeof b.image === 'number' ? ABOUT_IMAGES[b.image] : b.image;
  return `<div class="row${i%2 ? ' flip' : ''}">
    <div><h3>${esc(b.title)}</h3><p class="sub">${esc(b.sub)}</p><ul>${b.bullets.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>
    <div class="pic"><img src="${esc(img)}" alt="${esc(b.title)}" loading="lazy"></div>
  </div>`;
}).join('');
$('footer').textContent = `© ${new Date().getFullYear()} ${SITE_NAME}`;

// team (name/photo left blank are filled from Discord by the backend)
function drawTeam(info){
  $('tgrid').innerHTML = TEAM.map(m => {
    const i = info[m.id] || {};
    const name = m.name || i.name || m.role, photo = m.photo || i.avatar || '';
    return `<div class="member">
      <img src="${esc(photo)}" alt=""${photo ? '' : ' style="visibility:hidden"'}>
      <div><h3>${esc(name)}</h3><span>${esc(m.role)}</span>
      <a class="btn" href="https://discord.com/users/${m.id}" target="_blank" rel="noopener">Contact</a></div>
    </div>`;
  }).join('');
  document.querySelectorAll('.member img').forEach(im => im.addEventListener('error', () => { im.style.visibility = 'hidden'; }));
}
drawTeam({});
fetch(TEAM_URL).then(r => r.ok ? r.json() : {}).then(drawTeam).catch(() => {});

// mobile menu
$('menuBtn').onclick = () => $('links').classList.toggle('open');
$('links').addEventListener('click', e => { if (e.target.closest('a')) $('links').classList.remove('open'); });

// star picker
function drawRate(){
  $('rate').innerHTML = [1,2,3,4,5].map(n => `<button type="button" class="${n<=stars?'on':''}" data-n="${n}" aria-label="${n} stars">★</button>`).join('');
}
$('rate').onclick = e => { const b = e.target.closest('button'); if (b){ stars = +b.dataset.n; drawRate(); } };
drawRate();

// reviews
let hasReview = false;
function renderReviews(list){
  if (!list.length){ $('track').innerHTML = '<p class="note">No reviews yet.</p>'; return; }
  $('track').innerHTML = list.map(r => `<div class="rev"><b>${esc(r.name)}</b><div class="stars">${'★'.repeat(r.stars||5)}</div><p>${esc(r.text)}</p></div>`).join('');
}
// scroll the strip: arrows, mouse drag, or swipe / shift+wheel
const strip = $('track').parentElement;
$('revPrev').onclick = () => strip.scrollBy({left: -528, behavior: 'smooth'});
$('revNext').onclick = () => strip.scrollBy({left: 528, behavior: 'smooth'});
let drag = null;
strip.addEventListener('pointerdown', e => { if (e.pointerType === 'mouse') { drag = {x: e.clientX, left: strip.scrollLeft}; strip.classList.add('drag'); } });
window.addEventListener('pointermove', e => { if (drag) strip.scrollLeft = drag.left - (e.clientX - drag.x); });
window.addEventListener('pointerup', () => { drag = null; strip.classList.remove('drag'); });
async function loadReviews(initial = true){
  try{
    const r = await fetch(REVIEWS_URL, {credentials:'include'});
    if (!r.ok) throw 0;
    const list = await r.json();
    renderReviews(list);
    const mine = list.find(x => x.mine);
    hasReview = !!mine;
    $('postBtn').textContent = mine ? 'Save changes' : 'Post review';
    if (mine && !$('reviewText').value){ stars = mine.stars || 5; drawRate(); $('reviewText').value = mine.text; }
    if (initial) $('reviewNote').textContent = mine ? 'You already reviewed us. You can edit your review here.' : '';
  }catch{ renderReviews([]); }
}
$('postBtn').onclick = async () => {
  const text = $('reviewText').value.trim();
  if (text.length < 3){ $('reviewNote').textContent = 'Write at least a few words.'; return; }
  $('postBtn').disabled = true;
  try{
    const r = await fetch(REVIEWS_URL, {method:'POST', credentials:'include', headers:{'Content-Type':'application/json','X-Requested-With':'panel'}, body:JSON.stringify({stars, text})});
    if (!r.ok) throw 0;
    await loadReviews(false);
    $('reviewNote').textContent = 'Review saved. You can edit it any time.';
  }catch{ $('reviewNote').textContent = 'Could not save your review. Try again.'; }
  $('postBtn').disabled = false;
};

// login state
async function loadMe(){
  try{
    const r = await fetch(ME_URL, {credentials:'include'});
    if (!r.ok) throw 0;
    user = await r.json();
  }catch{ user = null; }
  $('loginBtn').classList.toggle('hidden', !!user);
  $('userBox').classList.toggle('hidden', !user);
  $('reviewForm').classList.toggle('hidden', !user);
  $('reviewLogin').classList.toggle('hidden', !!user);
  if (user){
    $('userName').textContent = user.username;
    $('userPfp').src = user.avatar && user.avatar.startsWith('http') ? user.avatar
      : user.avatar ? `https://cdn.discordapp.com/avatars/${user.id}/${user.avatar}.png?size=64`
      : 'https://cdn.discordapp.com/embed/avatars/0.png';
  }
}
$('logoutBtn').onclick = async () => { try{ await fetch(LOGOUT_URL, {method:'POST', credentials:'include', headers:{'X-Requested-With':'panel'}}); }catch{} location.reload(); };

loadMe(); loadReviews();
